  /**
   * List materializations for a dataset (Deprecated) (auto-paginate all pages)
   *
   * Source docs: https://help.sigmacomputing.com/reference/listdatasetmaterializations
   *
   * List materialization jobs for a dataset.
   *
   *   **Deprecation notice**: [Datasets](doc:datasets) are deprecated. Starting June 2, 2026, you will no longer be able to create datasets or edit existing datasets. Migrate your datasets to data models and update any documents that use datasets as a data source to use a different source. See [Migrate a dataset to a data model](doc:migrate-a-dataset-to-a-data-model).
   *
   *   ### Usage notes
   *   - Retrieve the **datasetId** by calling the [/v2/datasets](listdatasets) endpoint.
   *
   * @param datasetId
   * @param query - Query parameters
   * @yields ListDatasetMaterializationsResponse
   */
  listMaterializationsAll(
    datasetId: string,
    query?: ListDatasetMaterializationsQuery,
  ): PaginatedAsyncGenerator<
    DeepReadonly<ListDatasetMaterializationsResponse>
  > {
    // eslint-disable-next-line @typescript-eslint/no-this-alias
    const resource = this;
    async function* gen() {
      let cursor: string | undefined;
      do {
        const page = await resource.listMaterializations(datasetId, {
          ...query,
          page: cursor,
        } as ListDatasetMaterializationsQuery);
        yield page;
        cursor = (page as { nextPage?: string | null })['nextPage'] as
          string | undefined;
      } while (cursor);
    }
    return new PaginatedAsyncGenerator(gen());
  }

